USE icap_platform_english;
UPDATE tasks SET title='Task 1: if-else Conditionals', description='Learn if-else conditional statements, output pass or fail based on score', content_json='{\"a_stage\":{\"python_code\":\"score = 85\\nif score >= 60:\\n    print(\\\"Pass\\\")\\nelse:\\n    print(\\\"Fail\\\")\"},\"c_stage\":{\"title\":\"Determine Grade（Nested if）\",\"blocks_xml\":\"<xml xmlns=\\\"https://developers.google.com/blockly/xml\\\">\\n  <block type=\\\"variables_set\\\">\\n    <field name=\\\"VAR\\\">score</field>\\n    <value name=\\\"VALUE\\\">\\n      <block type=\\\"math_number\\\">\\n        <field name=\\\"NUM\\\">85</field>\\n      </block>\\n    </value>\\n    <next>\\n      <block type=\\\"controls_if\\\">\\n        <value name=\\\"IF0\\\">\\n          <block type=\\\"logic_compare\\\">\\n            <field name=\\\"OP\\\">GTE</field>\\n            <value name=\\\"A\\\">\\n              <block type=\\\"variables_get\\\">\\n                <field name=\\\"VAR\\\">score</field>\\n              </block>\\n            </value>\\n            <value name=\\\"B\\\">\\n              <block type=\\\"math_number\\\">\\n                <field name=\\\"NUM\\\">90</field>\\n              </block>\\n            </value>\\n          </block>\\n        </value>\\n        <statement name=\\\"DO0\\\">\\n          <block type=\\\"text_print\\\">\\n            <value name=\\\"TEXT\\\">\\n              <block type=\\\"text\\\">\\n                <field name=\\\"TEXT\\\">Excellent</field>\\n              </block>\\n            </value>\\n          </block>\\n        </statement>\\n        <statement name=\\\"ELSE\\\">\\n          <block type=\\\"controls_if\\\">\\n            <value name=\\\"IF0\\\">\\n              <block type=\\\"logic_compare\\\">\\n                <field name=\\\"OP\\\">GTE</field>\\n                <value name=\\\"A\\\">\\n                  <block type=\\\"variables_get\\\">\\n                    <field name=\\\"VAR\\\">score</field>\\n                  </block>\\n                </value>\\n                <value name=\\\"B\\\">\\n                  <block type=\\\"math_number\\\">\\n                    <field name=\\\"NUM\\\">60</field>\\n                  </block>\\n                </value>\\n              </block>\\n            </value>\\n            <statement name=\\\"DO0\\\">\\n              <block type=\\\"text_print\\\">\\n                <value name=\\\"TEXT\\\">\\n                  <block type=\\\"text\\\">\\n                    <field name=\\\"TEXT\\\">Pass</field>\\n                  </block>\\n                </value>\\n              </block>\\n            </statement>\\n            <statement name=\\\"ELSE\\\">\\n              <block type=\\\"text_print\\\">\\n                <value name=\\\"TEXT\\\">\\n                  <block type=\\\"text\\\">\\n                    <field name=\\\"TEXT\\\">Fail</field>\\n                  </block>\\n                </value>\\n              </block>\\n            </statement>\\n          </block>\\n        </statement>\\n      </block>\\n    </next>\\n  </block>\\n</xml>\",\"answer_code\":\"score = 85\\nif score >= 90:\\n    print(\\\"Excellent\\\")\\nelse:\\n    if score >= 60:\\n        print(\\\"Pass\\\")\\n    else:\\n        print(\\\"Not Pass\\\")\",\"description\":\"Determine grade: 90 or above is Excellent, 60 or above is Pass, otherwise Fail. Note: this uses nested if: first check >=90, if false, then check >=60.\",\"code_skeleton\":\"\",\"expected_output\":\"Pass\"},\"i_stage\":{\"summary_points\":[\"if-else is used for conditional branching\",\"Comparison operators return True or False\",\"Indentation distinguishes code blocks\",\"Nested if enables multi-level decisions\"],\"question_prompts\":[\"What would be output if the score is exactly 60?\",\"What would happen if we changed >= to >?\"]},\"p_stage\":{\"subtasks\":[{\"id\":1,\"title\":\"Get variable\",\"blocks\":[{\"color\":\"orange\",\"block_id\":\"variables_set\",\"block_type\":\"Variable assignment\",\"explanation\":\"Create a variable score and store 85 in it.\",\"python_code\":\"score = 85\"}]},{\"id\":2,\"title\":\"Conditional Judgment\",\"blocks\":[{\"color\":\"blue\",\"block_id\":\"controls_if\",\"block_type\":\"if-else judgment\",\"explanation\":\"if is followed by a condition. If the condition is true, the code inside the if block is executed. Note the colon and indentation.\",\"python_code\":\"if score >= 60:\\n    print(\'Pass\')\\nelse:\\n    print(\'Not Pass\')\"},{\"color\":\"orange\",\"block_id\":\"logic_compare\",\"block_type\":\"Comparison operators\",\"explanation\":\">= means greater than or equal to. The comparison result is either True or False.\",\"python_code\":\"score >= 60\"}]},{\"id\":3,\"title\":\"Output result\",\"blocks\":[{\"color\":\"green\",\"block_id\":\"text_print\",\"block_type\":\"print output\",\"explanation\":\"print() displays the content on the screen.\",\"python_code\":\"print(\'Pass\')\"}]}]},\"inferred_blocks\":{\"text\":{\"count\":2,\"fields\":{\"TEXT\":[\"Pass\",\"Fail\"]}},\"text_print\":{\"count\":2},\"controls_if\":{\"count\":1},\"math_number\":{\"count\":2,\"fields\":{\"NUM\":[\"85\",\"60\"]}},\"logic_compare\":{\"count\":1,\"fields\":{\"OP\":[\"GTE\"]}},\"variables_set\":{\"count\":1,\"fields\":{\"VAR\":[\"score\"]}}}}' WHERE id=1;
UPDATE tasks SET title='Task 2: for Loop Repetition', description='Learn for loops to make the computer repeat actions automatically', content_json='{\"a_stage\":{\"python_code\":\"for i in range(5):\\n    print(\\\"-\\\")\"},\"c_stage\":{\"title\":\"Countdown\",\"blocks_xml\":\"<xml xmlns=\\\"http://www.w3.org/1999/xhtml\\\">\\n  <block type=\\\"variables_set\\\">\\n    <field name=\\\"VAR\\\">n</field>\\n    <value name=\\\"VALUE\\\">\\n      <block type=\\\"math_number\\\">\\n        <field name=\\\"NUM\\\">5</field>\\n      </block>\\n    </value>\\n    <next>\\n      <block type=\\\"controls_repeat_ext\\\">\\n        <value name=\\\"TIMES\\\">\\n          <block type=\\\"math_number\\\">\\n            <field name=\\\"NUM\\\">5</field>\\n          </block>\\n        </value>\\n        <statement name=\\\"DO\\\">\\n          <block type=\\\"text_print\\\">\\n            <value name=\\\"TEXT\\\">\\n              <block type=\\\"variables_get\\\">\\n                <field name=\\\"VAR\\\">n</field>\\n              </block>\\n            </value>\\n            <next>\\n              <block type=\\\"variables_set\\\">\\n                <field name=\\\"VAR\\\">n</field>\\n                <value name=\\\"VALUE\\\">\\n                  <block type=\\\"math_arithmetic\\\">\\n                    <field name=\\\"OP\\\">MINUS</field>\\n                    <value name=\\\"A\\\">\\n                      <block type=\\\"variables_get\\\">\\n                        <field name=\\\"VAR\\\">n</field>\\n                      </block>\\n                    </value>\\n                    <value name=\\\"B\\\">\\n                      <block type=\\\"math_number\\\">\\n                        <field name=\\\"NUM\\\">1</field>\\n                      </block>\\n                    </value>\\n                  </block>\\n                </value>\\n              </block>\\n            </next>\\n          </block>\\n        </statement>\\n      </block>\\n    </next>\\n  </block>\\n</xml>\",\"answer_code\":\"n = 5\\nfor _ in range(5):\\n    print(n)\\n    n = n - 1\",\"description\":\"Countdown from 5 to 1. Use a variable n=5, loop 5 times, output each time then n minus 1.\",\"code_skeleton\":\"\",\"expected_output\":\"5\\n4\\n3\\n2\\n1\"},\"i_stage\":{\"summary_points\":[\"for loop repeats code execution\",\"range(n) generates numbers from 0 to n-1\",\"Indentation determines what belongs to the loop body\",\"Variable i takes a different value each loop iteration\"],\"question_prompts\":[\"range(5) loops 5 times but i goes from 0 to 4. Why?\",\"To draw a triangle with 7 rows, what would we change?\"]},\"p_stage\":{\"subtasks\":[{\"id\":1,\"title\":\"for loop structure\",\"blocks\":[{\"color\":\"blue\",\"block_id\":\"controls_repeat_ext\",\"block_type\":\"Repeat N times\",\"explanation\":\"range(5) means repeat 5 times. The code inside must be indented.\",\"python_code\":\"for i in range(5):\\n    print(\'-\')\"},{\"color\":\"orange\",\"block_id\":\"math_number\",\"block_type\":\"Number\",\"explanation\":\"The 5 in range(5) sets the loop count. Change to 3 to loop 3 times.\",\"python_code\":\"5\"}]},{\"id\":2,\"title\":\"print in Loop\",\"blocks\":[{\"color\":\"green\",\"block_id\":\"text_print\",\"block_type\":\"print output\",\"explanation\":\"This print is inside the loop, so it runs 5 times, printing 5 dashes on screen.\",\"python_code\":\"print(\'-\')\"}]}]},\"inferred_blocks\":{\"text\":{\"count\":1,\"fields\":{\"TEXT\":[\"-\"]}},\"text_print\":{\"count\":1},\"math_number\":{\"count\":1,\"fields\":{\"NUM\":[\"5\"]}},\"controls_repeat_ext\":{\"count\":1}}}' WHERE id=2;
UPDATE tasks SET title='Task 3: Input and Conditionals', description='Learn to use input() to get user input and respond differently based on conditions', content_json='{\"a_stage\":{\"python_code\":\"name = input(\\\"Enter your name:\\\")\\nprint(\\\"Hello, \\\" + name)\"},\"c_stage\":{\"title\":\"Check Name Length\",\"blocks_xml\":\"<xml xmlns=\\\"https://developers.google.com/blockly/xml\\\">\\n  <block type=\\\"variables_set\\\">\\n    <field name=\\\"VAR\\\">name</field>\\n    <value name=\\\"VALUE\\\">\\n      <block type=\\\"sensing_ask\\\">\\n        <value name=\\\"PROMPT\\\">\\n          <block type=\\\"text\\\">\\n            <field name=\\\"TEXT\\\">Enter your name:</field>\\n          </block>\\n        </value>\\n      </block>\\n    </value>\\n    <next>\\n      <block type=\\\"controls_if\\\">\\n        <value name=\\\"IF0\\\">\\n          <block type=\\\"logic_compare\\\">\\n            <field name=\\\"OP\\\">GT</field>\\n            <value name=\\\"A\\\">\\n              <block type=\\\"text_length\\\">\\n                <value name=\\\"VALUE\\\">\\n                  <block type=\\\"variables_get\\\">\\n                    <field name=\\\"VAR\\\">name</field>\\n                  </block>\\n                </value>\\n              </block>\\n            </value>\\n            <value name=\\\"B\\\">\\n              <block type=\\\"math_number\\\">\\n                <field name=\\\"NUM\\\">3</field>\\n              </block>\\n            </value>\\n          </block>\\n        </value>\\n        <statement name=\\\"DO0\\\">\\n          <block type=\\\"text_print\\\">\\n            <value name=\\\"TEXT\\\">\\n              <block type=\\\"text\\\">\\n                <field name=\\\"TEXT\\\">Long name</field>\\n              </block>\\n            </value>\\n          </block>\\n        </statement>\\n        <statement name=\\\"ELSE\\\">\\n          <block type=\\\"text_print\\\">\\n            <value name=\\\"TEXT\\\">\\n              <block type=\\\"text\\\">\\n                <field name=\\\"TEXT\\\">Short name</field>\\n              </block>\\n            </value>\\n          </block>\\n        </statement>\\n      </block>\\n    </next>\\n  </block>\\n</xml>\",\"answer_code\":\"name = input(\\\"Enter your name：\\\")\\nif len(name) > 3:\\n    print(\\\"Long name\\\")\\nelse:\\n    print(\\\"Short name\\\")\",\"description\":\"After entering a name, check the name length: if it is more than 3 characters, output [Long name]; otherwise, output [Short name]. Hint: Use len() to get the string length.\",\"code_skeleton\":\"\",\"expected_output\":\"Long name\"},\"i_stage\":{\"summary_points\":[\"input() gets user input and returns a string\",\"len() calculates string length\",\"Captured input can be stored in variables for reuse\",\"input + if enables interactive decision-making\"],\"question_prompts\":[\"If the user presses Enter without typing, what would len() return?\",\"Can we first use input() to get a Number, and then use if to check its size?\"]},\"p_stage\":{\"subtasks\":[{\"id\":1,\"title\":\"Get input\",\"blocks\":[{\"color\":\"green\",\"block_id\":\"sensing_ask\",\"block_type\":\"Ask and wait (input)\",\"explanation\":\"input() pauses the program to wait for user input. The prompt text goes in parentheses.\",\"python_code\":\"name = input(\'Enter your name:\')\"}]},{\"id\":2,\"title\":\"Store in Variable\",\"blocks\":[{\"color\":\"orange\",\"block_id\":\"variables_set\",\"block_type\":\"Variable assignment\",\"explanation\":\"Store what input() gets into the variable name.\",\"python_code\":\"name = ...\"}]},{\"id\":3,\"title\":\"Length Judgment\",\"blocks\":[{\"color\":\"purple\",\"block_id\":\"text_length\",\"block_type\":\"String length\",\"explanation\":\"len() returns the length of a string (how many characters). Input \'Tom\', len() returns 3.\",\"python_code\":\"len(name)\"}]},{\"id\":4,\"title\":\"Conditional Output\",\"blocks\":[{\"color\":\"blue\",\"block_id\":\"controls_if\",\"block_type\":\"if-else judgment\",\"explanation\":\"First use len() to get the name length, then use if to check if it\'s greater than 3.\",\"python_code\":\"if len(name) > 3:\\n    print(\'Long name\')\\nelse:\\n    print(\'Short name\')\"}]}]},\"inferred_blocks\":{\"text\":{\"count\":1,\"fields\":{\"TEXT\":[\"Hello, \"]}},\"text_join\":{\"count\":1},\"text_print\":{\"count\":1},\"sensing_ask\":{\"count\":1},\"variables_set\":{\"count\":1,\"fields\":{\"VAR\":[\"name\"]}}}}' WHERE id=3;
UPDATE tasks SET title='Task 4: Conditions in Loops', description='Combine for loops and if conditionals to classify and count data', content_json='{\"a_stage\":{\"python_code\":\"for i in range(10):\\n    if i % 2 == 0:\\n        print(\\\"Even\\\")\\n    else:\\n        print(\\\"Odd\\\")\"},\"c_stage\":{\"title\":\"Count Even Numbers\",\"blocks_xml\":\"<xml xmlns=\\\"https://developers.google.com/blockly/xml\\\">\\n  <block type=\\\"variables_set\\\">\\n    <field name=\\\"VAR\\\">count</field>\\n    <value name=\\\"VALUE\\\">\\n      <block type=\\\"math_number\\\">\\n        <field name=\\\"NUM\\\">0</field>\\n      </block>\\n    </value>\\n    <next>\\n      <block type=\\\"controls_repeat_ext\\\">\\n        <value name=\\\"TIMES\\\">\\n          <block type=\\\"math_number\\\">\\n            <field name=\\\"NUM\\\">10</field>\\n          </block>\\n        </value>\\n        <statement name=\\\"DO\\\">\\n          <block type=\\\"controls_if\\\">\\n            <value name=\\\"IF0\\\">\\n              <block type=\\\"math_arithmetic\\\">\\n                <field name=\\\"OP\\\">MODULO</field>\\n                <value name=\\\"A\\\">\\n                  <block type=\\\"variables_get\\\">\\n                    <field name=\\\"VAR\\\">i</field>\\n                  </block>\\n                </value>\\n                <value name=\\\"B\\\">\\n                  <block type=\\\"math_number\\\">\\n                    <field name=\\\"NUM\\\">2</field>\\n                  </block>\\n                </value>\\n              </block>\\n            </value>\\n            <statement name=\\\"DO0\\\">\\n              <block type=\\\"variables_set\\\">\\n                <field name=\\\"VAR\\\">count</field>\\n                <value name=\\\"VALUE\\\">\\n                  <block type=\\\"math_arithmetic\\\">\\n                    <field name=\\\"OP\\\">ADD</field>\\n                    <value name=\\\"A\\\">\\n                      <block type=\\\"variables_get\\\">\\n                        <field name=\\\"VAR\\\">count</field>\\n                      </block>\\n                    </value>\\n                    <value name=\\\"B\\\">\\n                      <block type=\\\"math_number\\\">\\n                        <field name=\\\"NUM\\\">1</field>\\n                      </block>\\n                    </value>\\n                  </block>\\n                </value>\\n              </block>\\n            </statement>\\n          </block>\\n        </statement>\\n        <next>\\n          <block type=\\\"text_print\\\">\\n            <value name=\\\"TEXT\\\">\\n              <block type=\\\"variables_get\\\">\\n                <field name=\\\"VAR\\\">count</field>\\n              </block>\\n            </value>\\n          </block>\\n        </next>\\n      </block>\\n    </next>\\n  </block>\\n</xml>\",\"answer_code\":\"count = 0\\nfor i in range(10):\\n    if i % 2 == 0:\\n        count = count + 1\\nprint(count)\",\"description\":\"Loop 10 times, count how many even numbers there are. Hint: Start with a variable count=0, increment count by 1 each time an even number is found.\",\"code_skeleton\":\"\",\"expected_output\":\"5\"},\"i_stage\":{\"summary_points\":[\"for Loop can iterate over a range ofNumber\",\"% Modulo Operationcan determine even or odd\",\"if can be placed inside a loop for per-iteration checks\",\"Using a counter variable is a common programming technique\"],\"question_prompts\":[\"If not counting even numbers, but counting odd numbers instead, where should the code be changed?\",\"Is count = count + 1 the same as count += 1?\"]},\"p_stage\":{\"subtasks\":[{\"id\":1,\"title\":\"Loop Review\",\"blocks\":[{\"color\":\"blue\",\"block_id\":\"controls_repeat_ext\",\"block_type\":\"Repeat N times\",\"explanation\":\"Review: for loop makes print(i) run 10 times, i from 0 to 9.\",\"python_code\":\"for i in range(10):\\n    print(i)\"}]},{\"id\":2,\"title\":\"Modulo Operation\",\"blocks\":[{\"color\":\"orange\",\"block_id\":\"math_arithmetic\",\"block_type\":\"Arithmetic (add/sub/mul/div/mod)\",\"explanation\":\"% is the modulo operator. i % 2 gives the remainder of i divided by 2. A remainder of 0 means i is even.\",\"python_code\":\"i % 2\"}]},{\"id\":3,\"title\":\"Condition in Loop\",\"blocks\":[{\"color\":\"blue\",\"block_id\":\"controls_if\",\"block_type\":\"if-else judgment\",\"explanation\":\"Place if inside the loop — each iteration runs the check once.\",\"python_code\":\"if i % 2 == 0:\\n    print(\'even\')\\nelse:\\n    print(\'odd\')\"}]}]},\"inferred_blocks\":{\"text\":{\"count\":2,\"fields\":{\"TEXT\":[\"Even\",\"Odd\"]}},\"text_print\":{\"count\":2},\"controls_if\":{\"count\":1},\"math_number\":{\"count\":3,\"fields\":{\"NUM\":[\"10\",\"2\",\"0\"]}},\"logic_compare\":{\"count\":1,\"fields\":{\"OP\":[\"EQ\"]}},\"math_arithmetic\":{\"count\":1,\"fields\":{\"OP\":[\"MODULO\"]}},\"controls_repeat_ext\":{\"count\":1}}}' WHERE id=4;
